func TestSwarmRetirementRechecksAfterDrainAndLaunchTimeout(t *testing.T) {
	scaler, hosts, pass := swarmScaler(t)
	if err := scaler.cordon(t.Context(), pass); err != nil {
		t.Fatal(err)
