	for _, want := range []string{"ts_orch_authority_epoch 4", `ts_orch_js_stream_leader_local{stream="TS_CONTROL_LOG"} 1`,
		`ts_orch_js_consumer_num_pending{stream="TS_DELIVERY_INTENTS",consumer="TS_DELIVERY_WORKER"} 5`,
