func newSwarmHosts(t *testing.T) *swarmHosts {
	t.Helper()
	raftNode := raft.NewNode(raft.NodeOptions{ID: "scaler-manager", Addr: "127.0.0.1:1", StateDir: t.TempDir(),
		TickInterval: 10 * time.Millisecond, TLSCredentials: insecure.NewCredentials(), KeyRotator: &scalerKeys{key: makeKey()}})
	if err := raftNode.JoinAndStart(t.Context()); err != nil {
		t.Fatal(err)
	}
	done := make(chan error, 1)
	go func() { done <- raftNode.Run(t.Context()) }()
	t.Cleanup(func() { raftNode.Cancel(); <-done })
	deadline := time.Now().Add(10 * time.Second)
	for !raftNode.ReadyForProposals() {
		if time.Now().After(deadline) {
			t.Fatal("embedded manager did not elect a leader")
		}
		time.Sleep(10 * time.Millisecond)
	}
	memory := raftNode.MemoryStore()
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	server := grpc.NewServer()
	api.RegisterControlServer(server, controlapi.NewServer(memory, raftNode, nil, nil, nil))
	go func() { _ = server.Serve(listener) }()
	conn, err := grpc.NewClient(listener.Addr().String(), grpc.WithTransportCredentials(insecure.NewCredentials()))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = conn.Close(); server.Stop() })
	return &swarmHosts{live: map[string]bool{}, instanceIDs: map[string]string{}, store: memory, control: api.NewControlClient(conn)}
}

func (h *swarmHosts) sync(t *testing.T) {
	t.Helper()
	if err := h.store.Update(func(tx store.Tx) error {
		for name, live := range h.live {
			node := store.GetNode(tx, name)
			create := node == nil
			if create {
				node = &api.Node{ID: name, Role: api.NodeRoleWorker, Spec: api.NodeSpec{DesiredRole: api.NodeRoleWorker, Membership: api.NodeMembershipAccepted,
					Annotations: api.Annotations{Name: name, Labels: map[string]string{"terrascale.instance-id": "ocid-" + name, "terrascale.region": "sa-saopaulo-1"}}}}
				if nodeNumber(name) < FirstPoolNode {
					node.Role = api.NodeRoleManager
					node.Certificate.Role = api.NodeRoleManager
					node.Spec.DesiredRole = api.NodeRoleManager
				}
			}
			if id := h.instanceIDs[name]; id != "" {
				node.Spec.Annotations.Labels["terrascale.instance-id"] = id
			}
			node.Status.State = api.NodeStatus_DOWN
			if live {
				node.Status.State = api.NodeStatus_READY
			}
			if create {
				if err := store.CreateNode(tx, node); err != nil {
					return err
				}
			} else if err := store.UpdateNode(tx, node); err != nil {
				return err
			}
		}
		for i, desired := range h.desired {
			id := fmt.Sprintf("task-%d", i)
			serviceID := "service-" + desired.Role
			if store.GetService(tx, serviceID) == nil {
				if err := store.CreateService(tx, &api.Service{ID: serviceID, Spec: api.ServiceSpec{Annotations: api.Annotations{Name: serviceID, Labels: map[string]string{"terrascale.role": desired.Role}}}}); err != nil {
					return err
				}
			}
			task := store.GetTask(tx, id)
			create := task == nil
			if create {
				task = &api.Task{ID: id, NodeID: desired.Node, ServiceID: serviceID, DesiredState: api.TaskStateRunning, Status: api.TaskStatus{State: api.TaskStateRunning}}
			}
			if desired.Withdrawn {
				task.DesiredState = api.TaskStateShutdown
				task.Status.State = api.TaskStateShutdown
			}
			if create {
				if err := store.CreateTask(tx, task); err != nil {
					return err
				}
			} else if err := store.UpdateTask(tx, task); err != nil {
				return err
			}
		}
		return nil
	}); err != nil {
		t.Fatal(err)
	}
}

func (s *Scaler) observe(pool PoolState, hosts []*api.Node) observation {
	obs := observation{live: map[string]bool{}, counted: map[string]bool{}, addresses: map[string]string{}}
	byInstance := nodesByInstance(hosts)
	for _, node := range byInstance {
		if s.admitted(node, api.NodeRoleManager) && node.Status.State == api.NodeStatus_READY {
			obs.quorum++
			obs.live[node.Spec.Annotations.Name] = true
			obs.counted[node.Spec.Annotations.Name] = true
		}
	}
	for _, in := range pool.Instances {
		if in.Birth != nil && s.named(in.Name) {
			obs.addresses[in.Name] = in.PrivateIP
		}
		if absent(in.State) {
			continue
		}
		obs.pool++
		if node := byInstance[in.ID]; in.Birth != nil && s.admitted(node, api.NodeRoleWorker) && node.Spec.Annotations.Name == in.Birth.Node && node.Status.State == api.NodeStatus_READY {
			obs.live[in.Name] = true
			obs.counted[in.Name] = true
		}
	}
	obs.nodes = obs.quorum + obs.pool
	return obs
}

func nodesByInstance(nodes []*api.Node) map[string]*api.Node {
	byInstance := make(map[string]*api.Node, len(nodes))
	for _, node := range nodes {
		id := node.Spec.Annotations.Labels["terrascale.instance-id"]
		if id == "" {
			continue
		}
		if _, exists := byInstance[id]; exists {
			byInstance[id] = nil
			continue
		}
		byInstance[id] = node
	}
	return byInstance
}

func (s *Scaler) admitted(node *api.Node, role api.NodeRole) bool {
	region, ok := catalog.LookupName(s.Cell)
	return ok && node != nil && node.Spec.Annotations.Name != "" &&
		node.Spec.Annotations.Labels["terrascale.region"] == region.OCIRegion &&
		node.Role == role && node.Certificate.Role == role && node.Spec.DesiredRole == role && node.Spec.Membership == api.NodeMembershipAccepted
}

func countedLoads(loads []NodeLoad, obs observation) []NodeLoad {
	var counted []NodeLoad
	for _, load := range loads {
		if obs.counted[load.Node] {
			counted = append(counted, load)
		}
	}
	return counted
}

func (s *Scaler) expiredSafe(ctx context.Context, t *tick, instance PoolInstance) error {
	if s.CanRetire == nil {
		return errors.New("node retirement safety proof is unavailable")
	}
	if err := s.CanRetire(ctx, instance.Name, instance.ID); err != nil {
		return err
	}
	nodes, err := s.Control.ListNodes(ctx, &api.ListNodesRequest{})
	if err != nil {
		return err
	}
	for _, node := range nodes.Nodes {
		if node.Spec.Annotations.Labels["terrascale.instance-id"] != instance.ID {
			continue
		}
		safe, err := s.retireSafe(ctx, instance.Name, instance.ID)
		if err != nil {
			return err
		}
		if !safe {
			return errors.New("the admitted node holds protected tasks or has an unverified identity")
		}
		if err := s.setAvailability(ctx, instance.Name, instance.ID, api.NodeAvailabilityDrain, t.epoch); err != nil {
			return err
		}
		probe := *t
		probe.record.Action = &InFlight{Node: instance.Name, InstanceID: instance.ID}
		drained, err := s.drained(ctx, &probe)
		if err != nil {
			return err
		}
		if !drained {
			return errors.New("the admitted node has not finished draining")
		}
	}
	return nil
}

func (s *Scaler) cordon(ctx context.Context, t *tick) error {
	action := t.record.Action
	if err := s.Leader.Guard(ctx, t.epoch); err != nil {
		return err
	}
	safe, err := s.retireSafe(ctx, action.Node, action.InstanceID)
	if err != nil {
		t.pool.Pending = err.Error()
		return nil
	}
	if !safe {
		t.pool.Pending = "node retirement safety is unavailable or the node holds protected tasks"
		return nil
	}
	if err := s.setAvailability(ctx, action.Node, action.InstanceID, api.NodeAvailabilityDrain, t.epoch); err != nil {
		return fmt.Errorf("cordon %s: %w", action.Node, err)
	}
	action.Step = stepDrain
	return nil
}

func (s *Scaler) drained(ctx context.Context, t *tick) (bool, error) {
	node := t.record.Action.Node
	n, err := s.worker(ctx, node, t.record.Action.InstanceID)
	if err != nil {
		return false, err
	}
	if n.Spec.Availability != api.NodeAvailabilityDrain {
		return false, nil
	}
	tasks, err := s.Control.ListTasks(ctx, &api.ListTasksRequest{Filters: &api.ListTasksRequest_Filters{NodeIDs: []string{n.ID}}})
	if err != nil {
		return false, fmt.Errorf("list tasks at %s: %w", node, err)
	}
	for _, task := range tasks.Tasks {
		// Desired SHUTDOWN or manager orphaning cannot prove the agent stopped the process.
		if task.Status.State < api.TaskStateCompleted || task.Status.State == api.TaskStateOrphaned {
			return false, nil
		}
	}
	backends, err := s.Backends(ctx, node, t.obs.addresses[node])
	if err != nil {
		return false, fmt.Errorf("count load balancer backends at %s: %w", node, err)
	}
	return backends == 0, nil
}

func (s *Scaler) remove(ctx context.Context, t *tick) error {
	action := t.record.Action
	if err := s.Leader.Guard(ctx, t.epoch); err != nil {
		return err
	}
	safe, err := s.retireSafe(ctx, action.Node, action.InstanceID)
	if err != nil {
		t.pool.Pending = err.Error()
		return nil
	}
	if !safe {
		t.pool.Pending = "node retirement safety is unavailable or the node holds protected tasks"
		return nil
	}
	drained, err := s.drained(ctx, t)
	if err != nil {
		return err
	}
	if !drained {
		action.Step = stepDrain
		return nil
	}
	if err := s.Leader.Guard(ctx, t.epoch); err != nil {
		return err
	}
	retirement, err := s.Pool.PrepareRetirement(ctx, action.InstanceID, action.ID)
	if err != nil {
		t.pool.Pending = err.Error()
		return nil
	}
	t.record.Retirement = new(retirement)
	return nil
}

func (s *Scaler) pickDrain(ctx context.Context, t *tick) (PoolInstance, bool, error) {
	protected, err := s.protectedNodes(ctx)
	if err != nil {
		return PoolInstance{}, false, err
	}
	nodes, err := s.Control.ListNodes(ctx, &api.ListNodesRequest{})
	if err != nil {
		return PoolInstance{}, false, fmt.Errorf("list drain candidates: %w", err)
	}
	workers := nodesByInstance(nodes.Nodes)
	cpu := map[string]float64{}
	for _, load := range t.loads {
		cpu[load.Node] = load.CPU
	}
	var candidates []PoolInstance
	for _, in := range t.pool.Instances {
		node := workers[in.ID]
		if _, loaded := cpu[in.Name]; loaded && t.obs.counted[in.Name] && s.named(in.Name) &&
			s.admitted(node, api.NodeRoleWorker) && node.Spec.Availability == api.NodeAvailabilityActive && !protected[node.ID] {
			candidates = append(candidates, in)
		}
	}
	if len(candidates) == 0 {
		return PoolInstance{}, false, nil
	}
	slices.SortFunc(candidates, func(a, b PoolInstance) int {
		return cmp.Or(cmp.Compare(cpu[a.Name], cpu[b.Name]), cmp.Compare(nodeNumber(b.Name), nodeNumber(a.Name)))
	})
	for _, candidate := range candidates {
		if s.CanRetire == nil {
			t.blocked = "node retirement safety proof is unavailable"
			break
		}
		if err := s.CanRetire(ctx, candidate.Name, candidate.ID); err != nil {
			t.blocked = fmt.Sprintf("cannot retire %s: %s", candidate.Name, err)
			continue
		}
		return candidate, true, nil
	}
	return PoolInstance{}, false, nil
}

func (s *Scaler) protectedNodes(ctx context.Context) (map[string]bool, error) {
	services, err := s.Control.ListServices(ctx, &api.ListServicesRequest{})
	if err != nil {
		return nil, fmt.Errorf("list services for retirement safety: %w", err)
	}
	known := map[string]*api.Service{}
	for _, service := range services.Services {
		known[service.ID] = service
	}
	tasks, err := s.Control.ListTasks(ctx, &api.ListTasksRequest{})
	if err != nil {
		return nil, fmt.Errorf("list tasks for retirement safety: %w", err)
	}
	protected := map[string]bool{}
	for _, task := range tasks.Tasks {
		service := known[task.ServiceID]
		if service == nil || service.Spec.Annotations.Labels["terrascale.role"] == "" ||
			stateful(service.Spec.Annotations.Labels) || stateful(task.Annotations.Labels) {
			protected[task.NodeID] = true
		}
	}
	return protected, nil
}

func stateful(labels map[string]string) bool {
	_, declared := labels["terrascale.stateful"]
	return declared || labels["terrascale.role"] == roleTerraBase
}

func (s *Scaler) worker(ctx context.Context, name, instanceID string) (*api.Node, error) {
	if name == "" || instanceID == "" {
		return nil, errors.New("worker retirement requires an exact node and OCI instance identity")
	}
	nodes, err := s.Control.ListNodes(ctx, &api.ListNodesRequest{})
	if err != nil {
		return nil, fmt.Errorf("find worker %s: %w", name, err)
	}
	node := nodesByInstance(nodes.Nodes)[instanceID]
	if !s.admitted(node, api.NodeRoleWorker) {
		return nil, fmt.Errorf("worker %s has no unique admitted OCI instance %s", name, instanceID)
	}
	return node, nil
}

func (s *Scaler) setAvailability(ctx context.Context, name, instanceID string, availability api.NodeSpec_Availability, epoch uint64) error {
	node, err := s.worker(ctx, name, instanceID)
	if err != nil {
		return err
	}
	if node.Spec.Annotations.Labels["terrascale.instance-id"] != instanceID {
		return fmt.Errorf("node %s is not instance %s", name, instanceID)
	}
	if node.Spec.Availability == availability {
		return nil
	}
	spec := node.Spec.Copy()
	spec.Availability = availability
	if err := s.Leader.Guard(ctx, epoch); err != nil {
		return err
	}
	_, err = s.Control.UpdateNode(ctx, &api.UpdateNodeRequest{NodeID: node.ID, NodeVersion: &node.Meta.Version, Spec: spec})
	return err
}

func (s *Scaler) retireSafe(ctx context.Context, name, instanceID string) (bool, error) {
	node, err := s.worker(ctx, name, instanceID)
	if err != nil {
		return false, err
	}
	protected, err := s.protectedNodes(ctx)
	if err != nil {
		return false, err
	}
	if node.Spec.Annotations.Labels["terrascale.instance-id"] != instanceID || protected[node.ID] || s.CanRetire == nil {
		return false, nil
	}
	if err := s.CanRetire(ctx, name, instanceID); err != nil {
		return false, fmt.Errorf("retirement safety for %s: %w", name, err)
	}
	return true, nil
}

func NewServer(store *store.MemoryStore, raft *raft.Node, securityConfig *ca.SecurityConfig, nv networkallocator.DriverValidator, dr *drivers.DriverProvider) *Server {
	if nv == nil {
		nv = networkallocator.InertProvider{}
	}
	return &Server{
		store:          store,
		dr:             dr,
		raft:           raft,
		securityConfig: securityConfig,
		netvalidator:   nv,
	}
}

func (s *Server) GetNode(_ context.Context, request *api.GetNodeRequest) (*api.GetNodeResponse, error) {
	if request.NodeID == "" {
		return nil, status.Error(codes.InvalidArgument, errInvalidArgument.Error())
	}

	var node *api.Node
	s.store.View(func(tx store.ReadTx) {
		node = store.GetNode(tx, request.NodeID)
	})
	if node == nil {
		return nil, status.Errorf(codes.NotFound, "node %s not found", request.NodeID)
	}

	if s.raft != nil {
		memberlist := s.raft.GetMemberlist()
		for _, member := range memberlist {
			if member.NodeID == node.ID {
				node.ManagerStatus = &api.ManagerStatus{
					RaftID:       member.RaftID,
					Addr:         member.Addr,
					Leader:       member.Status.Leader,
					Reachability: member.Status.Reachability,
				}
				break
			}
		}
	}

	return &api.GetNodeResponse{
		Node: node,
	}, nil
}

func (s *Server) ListNodes(_ context.Context, request *api.ListNodesRequest) (*api.ListNodesResponse, error) {
	var (
		nodes []*api.Node
		err   error
	)
	s.store.View(func(tx store.ReadTx) {
		switch {
		case request.Filters != nil && len(request.Filters.Names) > 0:
			nodes, err = store.FindNodes(tx, buildFilters(store.ByName, request.Filters.Names))
		case request.Filters != nil && len(request.Filters.NamePrefixes) > 0:
			nodes, err = store.FindNodes(tx, buildFilters(store.ByNamePrefix, request.Filters.NamePrefixes))
		case request.Filters != nil && len(request.Filters.IDPrefixes) > 0:
			nodes, err = store.FindNodes(tx, buildFilters(store.ByIDPrefix, request.Filters.IDPrefixes))
		case request.Filters != nil && len(request.Filters.Roles) > 0:
			filters := make([]store.By, 0, len(request.Filters.Roles))
			for _, v := range request.Filters.Roles {
				filters = append(filters, store.ByRole(v))
			}
			nodes, err = store.FindNodes(tx, store.Or(filters...))
		case request.Filters != nil && len(request.Filters.Memberships) > 0:
			filters := make([]store.By, 0, len(request.Filters.Memberships))
			for _, v := range request.Filters.Memberships {
				filters = append(filters, store.ByMembership(v))
			}
			nodes, err = store.FindNodes(tx, store.Or(filters...))
		default:
			nodes, err = store.FindNodes(tx, store.All)
		}
	})
	if err != nil {
		return nil, err
	}

	if request.Filters != nil {
		nodes = filterNodes(nodes,
			func(e *api.Node) bool {
				if len(request.Filters.Names) == 0 {
					return true
				}
				if e.Description == nil {
					return false
				}
				return filterContains(e.Description.Hostname, request.Filters.Names)
			},
			func(e *api.Node) bool {
				if len(request.Filters.NamePrefixes) == 0 {
					return true
				}
				if e.Description == nil {
					return false
				}
				return filterContainsPrefix(e.Description.Hostname, request.Filters.NamePrefixes)
			},
			func(e *api.Node) bool {
				return filterContainsPrefix(e.ID, request.Filters.IDPrefixes)
			},
			func(e *api.Node) bool {
				if len(request.Filters.Labels) == 0 {
					return true
				}
				if e.Description == nil {
					return false
				}
				return filterMatchLabels(e.Description.Engine.Labels, request.Filters.Labels)
			},
			func(e *api.Node) bool {
				if len(request.Filters.NodeLabels) == 0 {
					return true
				}
				return filterMatchLabels(e.Spec.Annotations.Labels, request.Filters.NodeLabels)
			},
			func(e *api.Node) bool {
				if len(request.Filters.Roles) == 0 {
					return true
				}
				for _, c := range request.Filters.Roles {
					if c == e.Role {
						return true
					}
				}
				return false
			},
			func(e *api.Node) bool {
				if len(request.Filters.Memberships) == 0 {
					return true
				}
				for _, c := range request.Filters.Memberships {
					if c == e.Spec.Membership {
						return true
					}
				}
				return false
			},
		)
	}

	// Add in manager information on nodes that are managers
	if s.raft != nil {
		memberlist := s.raft.GetMemberlist()

		for _, node := range nodes {
			for _, member := range memberlist {
				if member.NodeID == node.ID {
					node.ManagerStatus = &api.ManagerStatus{
						RaftID:       member.RaftID,
						Addr:         member.Addr,
						Leader:       member.Status.Leader,
						Reachability: member.Status.Reachability,
					}
					break
				}
			}
		}
	}

	return &api.ListNodesResponse{
		Nodes: nodes,
	}, nil
}

func (s *Server) UpdateNode(_ context.Context, request *api.UpdateNodeRequest) (*api.UpdateNodeResponse, error) {
	if request.NodeID == "" || request.NodeVersion == nil {
		return nil, status.Error(codes.InvalidArgument, errInvalidArgument.Error())
	}
	if err := validateNodeSpec(request.Spec); err != nil {
		return nil, err
	}

	var (
		node   *api.Node
		member *membership.Member
	)

	err := s.store.Update(func(tx store.Tx) error {
		node = store.GetNode(tx, request.NodeID)
		if node == nil {
			return status.Errorf(codes.NotFound, "node %s not found", request.NodeID)
		}

		// Demotion sanity checks.
		if node.Spec.DesiredRole == api.NodeRoleManager && request.Spec.DesiredRole == api.NodeRoleWorker {
			// Check for manager entries in Store.
			managers, err := store.FindNodes(tx, store.ByRole(api.NodeRoleManager))
			if err != nil {
				return status.Errorf(codes.Internal, "internal store error: %v", err)
			}
			if len(managers) == 1 && managers[0].ID == node.ID {
				return status.Errorf(codes.FailedPrecondition, "attempting to demote the last manager of the swarm")
			}

			// Check for node in memberlist
			if member = s.raft.GetMemberByNodeID(request.NodeID); member == nil {
				return status.Errorf(codes.NotFound, "can't find manager in raft memberlist")
			}

			// Quorum safeguard
			if !s.raft.CanRemoveMember(member.RaftID) {
				return status.Errorf(codes.FailedPrecondition, "can't remove member from the raft: this would result in a loss of quorum")
			}
		}

		node.Meta.Version = *request.NodeVersion
		node.Spec = *request.Spec.Copy()
		return store.UpdateNode(tx, node)
	})
	if err != nil {
		return nil, err
	}

	return &api.UpdateNodeResponse{
		Node: node,
	}, nil
}

func (s *Server) ListTasks(_ context.Context, request *api.ListTasksRequest) (*api.ListTasksResponse, error) {
	var (
		tasks []*api.Task
		err   error
	)

	s.store.View(func(tx store.ReadTx) {
		switch {
		case request.Filters != nil && len(request.Filters.Names) > 0:
			tasks, err = store.FindTasks(tx, buildFilters(store.ByName, request.Filters.Names))
		case request.Filters != nil && len(request.Filters.NamePrefixes) > 0:
			tasks, err = store.FindTasks(tx, buildFilters(store.ByNamePrefix, request.Filters.NamePrefixes))
		case request.Filters != nil && len(request.Filters.IDPrefixes) > 0:
			tasks, err = store.FindTasks(tx, buildFilters(store.ByIDPrefix, request.Filters.IDPrefixes))
		case request.Filters != nil && len(request.Filters.ServiceIDs) > 0:
			tasks, err = store.FindTasks(tx, buildFilters(store.ByServiceID, request.Filters.ServiceIDs))
		case request.Filters != nil && len(request.Filters.Runtimes) > 0:
			tasks, err = store.FindTasks(tx, buildFilters(store.ByRuntime, request.Filters.Runtimes))
		case request.Filters != nil && len(request.Filters.NodeIDs) > 0:
			tasks, err = store.FindTasks(tx, buildFilters(store.ByNodeID, request.Filters.NodeIDs))
		case request.Filters != nil && len(request.Filters.DesiredStates) > 0:
			filters := make([]store.By, 0, len(request.Filters.DesiredStates))
			for _, v := range request.Filters.DesiredStates {
				filters = append(filters, store.ByDesiredState(v))
			}
			tasks, err = store.FindTasks(tx, store.Or(filters...))
		default:
			tasks, err = store.FindTasks(tx, store.All)
		}

		if err != nil || request.Filters == nil {
			return
		}

		tasks = filterTasks(tasks,
			func(e *api.Task) bool {
				return filterContains(naming.Task(e), request.Filters.Names)
			},
			func(e *api.Task) bool {
				return filterContainsPrefix(naming.Task(e), request.Filters.NamePrefixes)
			},
			func(e *api.Task) bool {
				return filterContainsPrefix(e.ID, request.Filters.IDPrefixes)
			},
			func(e *api.Task) bool {
				return filterMatchLabels(e.ServiceAnnotations.Labels, request.Filters.Labels)
			},
			func(e *api.Task) bool {
				return filterContains(e.ServiceID, request.Filters.ServiceIDs)
			},
			func(e *api.Task) bool {
				return filterContains(e.NodeID, request.Filters.NodeIDs)
			},
			func(e *api.Task) bool {
				if len(request.Filters.Runtimes) == 0 {
					return true
				}
				r, err := naming.Runtime(e.Spec)
				if err != nil {
					return false
				}
				return filterContains(r, request.Filters.Runtimes)
			},
			func(e *api.Task) bool {
				if len(request.Filters.DesiredStates) == 0 {
					return true
				}
				for _, c := range request.Filters.DesiredStates {
					if c == e.DesiredState {
						return true
					}
				}
				return false
			},
			func(e *api.Task) bool {
				if !request.Filters.UpToDate {
					return true
				}

				service := store.GetService(tx, e.ServiceID)
				if service == nil {
					return false
				}

				n := store.GetNode(tx, e.NodeID)
				return !orchestrator.IsTaskDirty(service, e, n)
			},
		)
	})

	if err != nil {
		return nil, err
	}

	return &api.ListTasksResponse{
		Tasks: tasks,
	}, nil
}

func (s *Server) ListServices(_ context.Context, request *api.ListServicesRequest) (*api.ListServicesResponse, error) {
	var (
		services []*api.Service
		err      error
	)

	s.store.View(func(tx store.ReadTx) {
		switch {
		case request.Filters != nil && len(request.Filters.Names) > 0:
			services, err = store.FindServices(tx, buildFilters(store.ByName, request.Filters.Names))
		case request.Filters != nil && len(request.Filters.NamePrefixes) > 0:
			services, err = store.FindServices(tx, buildFilters(store.ByNamePrefix, request.Filters.NamePrefixes))
		case request.Filters != nil && len(request.Filters.IDPrefixes) > 0:
			services, err = store.FindServices(tx, buildFilters(store.ByIDPrefix, request.Filters.IDPrefixes))
		case request.Filters != nil && len(request.Filters.Runtimes) > 0:
			services, err = store.FindServices(tx, buildFilters(store.ByRuntime, request.Filters.Runtimes))
		default:
			services, err = store.FindServices(tx, store.All)
		}
	})
	if err != nil {
		switch err {
		case store.ErrInvalidFindBy:
			return nil, status.Error(codes.InvalidArgument, err.Error())
		default:
			return nil, err
		}
	}

	if request.Filters != nil {
		services = filterServices(services,
			func(e *api.Service) bool {
				return filterContains(e.Spec.Annotations.Name, request.Filters.Names)
			},
			func(e *api.Service) bool {
				return filterContainsPrefix(e.Spec.Annotations.Name, request.Filters.NamePrefixes)
			},
			func(e *api.Service) bool {
				return filterContainsPrefix(e.ID, request.Filters.IDPrefixes)
			},
			func(e *api.Service) bool {
				return filterMatchLabels(e.Spec.Annotations.Labels, request.Filters.Labels)
			},
			func(e *api.Service) bool {
				if len(request.Filters.Runtimes) == 0 {
					return true
				}
				r, err := naming.Runtime(e.Spec.Task)
				if err != nil {
					return false
				}
				return filterContains(r, request.Filters.Runtimes)
			},
		)
	}

	return &api.ListServicesResponse{
		Services: services,
	}, nil
}

func (s *MemoryStore) updateAt(proposer state.Proposer, appliedVersion *api.Version, cb func(Tx) error) error {
	defer metrics.StartTimer(updateLatencyTimer)()
	s.updateLock.Lock()
	memDBTx := s.memDB.Txn(true)

	var curVersion *api.Version

	if proposer != nil {
		curVersion = proposer.GetVersion()
	}

	var tx tx
	tx.init(memDBTx, curVersion)

	err := cb(&tx)

	commitGuard := make(chan struct{}, 1)
	commitGuard <- struct{}{}

	if err == nil {
		if proposer == nil {
			memDBTx.Commit()
			if len(tx.changelist) != 0 || appliedVersion != nil {
				s.appliedVersion = appliedVersion.Copy()
			}
		} else {
			var sa []api.StoreAction
			sa, err = tx.changelistStoreActions()

			if err == nil {
				if len(sa) != 0 {
					err = proposeAt(proposer, sa, func(version *api.Version) {
						select {
						case <-commitGuard:
							memDBTx.Commit()
							s.appliedVersion = version.Copy()
						default:
							// Already Abort()ed.
						}
					})
				} else {
					memDBTx.Commit()
				}
			}
		}
	}

	if err == nil {
		for _, c := range tx.changelist {
			s.queue.Publish(c)
		}
		if len(tx.changelist) != 0 {
			s.queue.Publish(state.EventCommit{Version: s.appliedVersion.Copy()})
		}
	} else {
		// The ProposeValue callback could still have executed, or be
		// executed in the near future. Guard against racing the
		// Commit().
		select {
		case <-commitGuard:
			memDBTx.Abort()
		default:
			// Already Abort()ed.
		}
	}
	s.updateLock.Unlock()
	return err
}

func (s *MemoryStore) Update(cb func(Tx) error) error {
	return s.update(s.proposer, cb)
}

