func testCollector(t *testing.T, member string, natsErr error) (*Collector, *atomic.Int32) {
	t.Helper()
	registry := NewRegistry(false)
	set := metrics.NewSet()
	set.NewCounter(Series(MetricPrefix+"member_total", "member", member)).Inc()
	registry.Register(set)
	health := new(Health)
	health.Add(Check{Name: "nats", Run: func(context.Context) (bool, string) { return natsErr == nil, "" }})
	natsCalls := new(atomic.Int32)
	collector, err := NewCollector(CollectorConfig{
		Cell: "gru", Member: member, Role: "controller", Registry: registry, Health: health,
		Authority: func() AuthorityView { return AuthorityView{Leader: true, Ready: true, Epoch: 4, Revision: 9} },
		NATS: func(context.Context) (NATSView, error) {
			natsCalls.Add(1)
			return NATSView{ServerName: "gru-" + member, Routes: 2, ClusterPeers: 3, IsMetaLeader: true,
				Streams:   []StreamView{{Name: "TS_CONTROL_LOG", Messages: 12, Replicas: 3, Leader: "gru-" + member}},
				Consumers: []ConsumerView{{Stream: "TS_DELIVERY_INTENTS", Name: "TS_DELIVERY_WORKER", NumPending: 5}},
			}, natsErr
		},
		Placement: func(context.Context) (PlacementView, error) {
			return PlacementView{StageCounts: map[string]int{"serving": 2, "awaiting-host": 1},
				Databases: []DatabaseView{{DatabaseID: "db", PartitionID: "p0", DesiredSeats: 3, Serving: 2,
					Rollout: &RolloutView{OperationID: "op", Seats: 3, Completed: 1}}}}, nil
		},
		OCI: func() OCIView {
			return OCIView{Operations: []OCIOperationView{{Service: "compute", Operation: "GET /instances/{id}", Calls: 2}}}
		},
		System: func() (SystemView, error) { return SystemView{CPUCount: 2, MemTotalBytes: 100}, nil },
	})
	if err != nil {
		t.Fatal(err)
	}
	return collector, natsCalls
}

func collectorHTTP(t *testing.T, collector *Collector) *httptest.Server {
	t.Helper()
	service, err := NewServer(Config{}, ServerDeps{Registry: collector.config.Registry, Health: new(Health), Snapshots: collector})
	if err != nil {
		t.Fatal(err)
	}
	endpoint := httptest.NewServer(service)
	t.Cleanup(endpoint.Close)
	return endpoint
}

func snapshotOverHTTP(t *testing.T, collector *Collector, metrics bool) (MemberSnapshot, error) {
	t.Helper()
	endpoint := collectorHTTP(t, collector)
	path := "/v1/snapshot"
	if metrics {
		path += "?metrics=1"
	}
	response, err := endpoint.Client().Get(endpoint.URL + path)
	if err != nil {
		return MemberSnapshot{}, err
	}
	defer response.Body.Close()
	var snapshot MemberSnapshot
	err = json.NewDecoder(response.Body).Decode(&snapshot)
	return snapshot, err
}

func (server *Server) HandleSnapshots(source SnapshotSource) {
	server.snapshots.Store(&source)
	server.snapshotOnce.Do(func() {
		server.Handle("GET /v1/snapshot", http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
			snapshot, err := (*server.snapshots.Load()).Snapshot(request.Context(),
				request.URL.Query().Get("metrics") == "1")
			if err != nil {
				writePlain(writer, http.StatusServiceUnavailable, "snapshot unavailable\n")
				return
			}
			writeJSON(writer, snapshot)
		}))
	})
}

func NewCollector(config CollectorConfig) (*Collector, error) {
	if config.Cell == "" || config.Member == "" || config.Role == "" {
		return nil, errors.New("observability collector requires a cell, member and role")
	}
	if config.MaxMetricsBytes <= 0 {
		config.MaxMetricsBytes = DefaultMaxMetricsBytes
	}
	if config.System == nil {
		filesystems := append([]FilesystemRole(nil), config.Filesystems...)
		config.System = func() (SystemView, error) { return ReadSystem(filesystems) }
	}
	collector := &Collector{config: config, startedAt: time.Now().UTC(), version: buildVersion()}
	collector.nats.TTL, collector.placement.TTL, collector.system.TTL = sectionCacheTTL, sectionCacheTTL, sectionCacheTTL
	collector.credentials.TTL = sectionCacheTTL
	config.Registry.RegisterWriter(collector.writeMetrics)
	return collector, nil
}

func (collector *Collector) Snapshot(ctx context.Context, includeMetrics bool) (MemberSnapshot, error) {
	config := collector.config
	snapshot := MemberSnapshot{Version: SnapshotVersion, Cell: config.Cell, Member: config.Member,
		Role: config.Role, BuildVersion: collector.version, StartedAt: collector.startedAt,
		ObservedAt: time.Now().UTC()}
	if config.Health != nil {
		snapshot.Ready, snapshot.Checks = config.Health.Evaluate(ctx)
	}
	fail := func(section string, err error) {
		if snapshot.Errors == nil {
			snapshot.Errors = map[string]string{}
		}
		snapshot.Errors[section] = errorClass(err)
	}
	if config.Authority != nil {
		view := config.Authority()
		snapshot.Authority = &view
	}
	if config.Links != nil {
		snapshot.Links = config.Links()
	}
	if view, err := collector.natsView(ctx); err != nil {
		fail("nats", err)
	} else if view != nil {
		snapshot.NATS = view
	}
	if view, err := collector.placementView(ctx); err != nil {
		fail("placement", err)
	} else if view != nil {
		snapshot.Placement = view
	}
	if config.Delivery != nil {
		view := config.Delivery()
		snapshot.Delivery = &view
	}
	if config.OCI != nil {
		view := config.OCI()
		snapshot.OCI = &view
	}
	if config.KVSnapshots != nil {
		view := config.KVSnapshots()
		snapshot.KVSnapshots = &view
	}
	if view, err := collector.systemView(ctx); err != nil {
		fail("system", err)
	} else {
		snapshot.System = &view
	}
	if config.Credentials != nil {
		// A partial list is still reported: one unreadable file must not
		// hide the expiry of the others.
		credentials, err := collector.credentials.Get(ctx, func(context.Context) ([]CredentialView, error) {
			return config.Credentials()
		})
		snapshot.Credentials = credentials
		if err != nil {
			fail("credentials", err)
		}
	}
	if includeMetrics && config.Registry != nil {
		snapshot.Metrics, snapshot.MetricsTruncated = config.Registry.Text(config.MaxMetricsBytes)
	}
	return snapshot, nil
}

func (collector *Collector) natsView(ctx context.Context) (*NATSView, error) {
	if collector.config.NATS == nil {
		return nil, nil
	}
	view, err := collector.nats.Get(ctx, collector.config.NATS)
	return &view, err
}

func (collector *Collector) placementView(ctx context.Context) (*PlacementView, error) {
	if collector.config.Placement == nil {
		return nil, nil
	}
	view, err := collector.placement.Get(ctx, collector.config.Placement)
	return &view, err
}

func (collector *Collector) systemView(ctx context.Context) (SystemView, error) {
	return collector.system.Get(ctx, func(context.Context) (SystemView, error) { return collector.config.System() })
}

func (collector *Collector) writeMetrics(w io.Writer) {
	ctx, cancel := context.WithTimeout(context.Background(), sectionTimeout)
	defer cancel()
	config := collector.config
	WriteGauge(w, Series(MetricPrefix+"build_info", "version", collector.version, "role", config.Role), 1)
	WriteGauge(w, MetricPrefix+"start_time_seconds", float64(collector.startedAt.Unix()))
	if config.Health != nil {
		ready, results := config.Health.Evaluate(ctx)
		WriteGauge(w, MetricPrefix+"ready", Bool(ready))
		for _, result := range results {
			WriteGauge(w, Series(MetricPrefix+"ready_check", "check", result.Name), Bool(result.OK))
		}
	}
	if config.Authority != nil {
		WriteAuthorityMetrics(w, config.Authority())
	}
	if view, err := collector.natsView(ctx); view != nil {
		WriteGauge(w, Series(MetricPrefix+"collect_ok", "section", "nats"), Bool(err == nil))
		if err == nil {
			WriteNATSMetrics(w, *view)
		}
	}
	if view, err := collector.placementView(ctx); view != nil {
		WriteGauge(w, Series(MetricPrefix+"collect_ok", "section", "placement"), Bool(err == nil))
		if err == nil {
			WritePlacementMetrics(w, *view)
		}
	}
	view, err := collector.systemView(ctx)
	WriteGauge(w, Series(MetricPrefix+"collect_ok", "section", "system"), Bool(err == nil))
	if err == nil {
		WriteSystemMetrics(w, view)
	}
	if config.Credentials != nil {
		credentials, err := collector.credentials.Get(ctx, func(context.Context) ([]CredentialView, error) {
			return config.Credentials()
		})
		WriteGauge(w, Series(MetricPrefix+"collect_ok", "section", "credentials"), Bool(err == nil))
		for _, credential := range credentials {
			WriteGauge(w, Series(MetricPrefix+"credential_expiry_timestamp_seconds", "name", credential.Name,
				"kind", credential.Kind), float64(credential.NotAfter.Unix()))
		}
	}
}

func (cache *Cache[T]) Get(ctx context.Context, load func(context.Context) (T, error)) (T, error) {
	cache.mu.Lock()
	if !cache.at.IsZero() && time.Since(cache.at) < cache.TTL {
		value, err := cache.value, cache.err
		cache.mu.Unlock()
		return value, err
	}
	flight := cache.flight
	if flight == nil {
		flight = &cacheFlight[T]{done: make(chan struct{})}
		cache.flight = flight
		// The load is shared, so no single caller's cancellation may cut
		// it short; sectionTimeout bounds it.
		loadCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), sectionTimeout)
		go func() {
			defer cancel()
			value, err := load(loadCtx)
			cache.mu.Lock()
			cache.value, cache.err, cache.at = value, err, time.Now()
			cache.flight = nil
			cache.mu.Unlock()
			flight.value, flight.err = value, err
			close(flight.done)
		}()
	}
	cache.mu.Unlock()
	select {
	case <-ctx.Done():
		var zero T
		return zero, ctx.Err()
	case <-flight.done:
		return flight.value, flight.err
	}
}

func errorClass(err error) string {
	switch {
	case errors.Is(err, context.DeadlineExceeded):
		return "timeout"
	case errors.Is(err, context.Canceled):
		return "canceled"
	default:
		return "unavailable"
	}
}

func (registry *Registry) WritePrometheus(w io.Writer) {
	if registry == nil {
		return
	}
	registry.mu.Lock()
	sets := slices.Clone(registry.sets)
	writers := slices.Clone(registry.writers)
	process := registry.processMetrics
	registry.mu.Unlock()
	if process {
		metrics.WriteProcessMetrics(w)
	}
	for _, set := range sets {
		set.WritePrometheus(w)
	}
	for _, write := range writers {
		write(w)
	}
}

func (registry *Registry) Text(limit int) (string, bool) {
	var buffer bytes.Buffer
	registry.WritePrometheus(&buffer)
	data := buffer.Bytes()
	if limit <= 0 || len(data) <= limit {
		return string(data), false
	}
	data = data[:limit]
	if cut := bytes.LastIndexByte(data, '\n'); cut >= 0 {
		data = data[:cut+1]
	} else {
		data = nil
	}
	return string(data), true
}

func Series(name string, pairs ...string) string {
	if len(pairs) < 2 {
		return name
	}
	var builder strings.Builder
	builder.WriteString(name)
	builder.WriteByte('{')
	for index := 0; index+1 < len(pairs); index += 2 {
		if index > 0 {
			builder.WriteByte(',')
		}
		builder.WriteString(pairs[index])
		builder.WriteString(`="`)
		builder.WriteString(escapeLabelValue(pairs[index+1]))
		builder.WriteByte('"')
	}
	builder.WriteByte('}')
	return builder.String()
}

func escapeLabelValue(value string) string {
	if !strings.ContainsAny(value, "\\\"\n") {
		return value
	}
	var builder strings.Builder
	for _, character := range value {
		switch character {
		case '\\':
			builder.WriteString(`\\`)
		case '"':
			builder.WriteString(`\"`)
		case '\n':
			builder.WriteString(`\n`)
		default:
			builder.WriteRune(character)
		}
	}
	return builder.String()
}

func WriteAuthorityMetrics(w io.Writer, view AuthorityView) {
	WriteGauge(w, MetricPrefix+"authority_leader", Bool(view.Leader))
	WriteGauge(w, MetricPrefix+"authority_ready", Bool(view.Ready))
	WriteGauge(w, MetricPrefix+"authority_can_mutate", Bool(view.CanMutate))
	WriteGauge(w, MetricPrefix+"authority_epoch", float64(view.Epoch))
	WriteGauge(w, MetricPrefix+"authority_revision", float64(view.Revision))
	if !view.ExpiresAt.IsZero() {
		WriteGauge(w, MetricPrefix+"authority_lease_expiry_timestamp_seconds", float64(view.ExpiresAt.Unix()))
	}
}

func WriteNATSMetrics(w io.Writer, view NATSView) {
	WriteGauge(w, MetricPrefix+"nats_connections", float64(view.Connections))
	WriteGauge(w, MetricPrefix+"nats_routes", float64(view.Routes))
	WriteGauge(w, MetricPrefix+"nats_cluster_peers", float64(view.ClusterPeers))
	WriteCounter(w, MetricPrefix+"nats_slow_consumers_total", float64(view.SlowConsumers))
	WriteCounter(w, MetricPrefix+"nats_in_msgs_total", float64(view.InMsgs))
	WriteCounter(w, MetricPrefix+"nats_out_msgs_total", float64(view.OutMsgs))
	WriteCounter(w, MetricPrefix+"nats_in_bytes_total", float64(view.InBytes))
	WriteCounter(w, MetricPrefix+"nats_out_bytes_total", float64(view.OutBytes))
	WriteGauge(w, MetricPrefix+"js_meta_leader", Bool(view.IsMetaLeader))
	WriteGauge(w, MetricPrefix+"js_meta_cluster_size", float64(view.MetaClusterSize))
	WriteGauge(w, MetricPrefix+"nats_view_truncated", Bool(view.Truncated))
	WriteGauge(w, Series(MetricPrefix+"nats_route_rtts_truncated", "server", view.ServerName), Bool(view.RouteRTTsTruncated))
	for _, route := range view.RouteRTTs {
		labels := []string{"server", view.ServerName, "peer", route.RemoteName}
		WriteGauge(w, Series(MetricPrefix+"nats_route_connections", labels...), float64(route.Connections))
		WriteGauge(w, Series(MetricPrefix+"nats_route_measured_connections", labels...), float64(route.MeasuredConnections))
		if route.RTTSeconds != nil {
			WriteGauge(w, Series(MetricPrefix+"nats_route_rtt_seconds", labels...), *route.RTTSeconds)
		}
	}
	offline := 0
	for _, peer := range view.MetaPeers {
		if peer.Offline {
			offline++
		}
		WriteGauge(w, Series(MetricPrefix+"js_meta_peer_lag", "peer", peer.Name), float64(peer.Lag))
	}
	WriteGauge(w, MetricPrefix+"js_meta_peers_offline", float64(offline))
	WriteGauge(w, MetricPrefix+"js_store_used_bytes", float64(view.StoreUsedBytes))
	WriteGauge(w, MetricPrefix+"js_store_limit_bytes", float64(view.StoreLimitBytes))
	for _, stream := range view.Streams {
		WriteGauge(w, Series(MetricPrefix+"js_stream_messages", "stream", stream.Name), float64(stream.Messages))
		WriteGauge(w, Series(MetricPrefix+"js_stream_bytes", "stream", stream.Name), float64(stream.Bytes))
		WriteGauge(w, Series(MetricPrefix+"js_stream_replicas", "stream", stream.Name), float64(stream.Replicas))
		WriteGauge(w, Series(MetricPrefix+"js_stream_replica_lag_max", "stream", stream.Name), float64(stream.MaxReplicaLag))
		WriteGauge(w, Series(MetricPrefix+"js_stream_offline_peers", "stream", stream.Name), float64(stream.OfflinePeers))
		WriteGauge(w, Series(MetricPrefix+"js_stream_leader_local", "stream", stream.Name),
			Bool(stream.Leader != "" && stream.Leader == view.ServerName))
	}
	for _, consumer := range view.Consumers {
		WriteGauge(w, Series(MetricPrefix+"js_consumer_num_pending", "stream", consumer.Stream, "consumer", consumer.Name),
			float64(consumer.NumPending))
		WriteGauge(w, Series(MetricPrefix+"js_consumer_num_ack_pending", "stream", consumer.Stream, "consumer", consumer.Name),
			float64(consumer.NumAckPending))
		WriteGauge(w, Series(MetricPrefix+"js_consumer_num_redelivered", "stream", consumer.Stream, "consumer", consumer.Name),
			float64(consumer.NumRedelivered))
	}
}

func WritePlacementMetrics(w io.Writer, view PlacementView) {
	stages := make([]string, 0, len(view.StageCounts))
	for stage := range view.StageCounts {
		stages = append(stages, stage)
	}
	slices.Sort(stages)
	for _, stage := range stages {
		WriteGauge(w, Series(MetricPrefix+"terrabase_members", "stage", stage), float64(view.StageCounts[stage]))
	}
	WriteGauge(w, MetricPrefix+"terrabase_partitions", float64(len(view.Databases)))
	// The partition count and per-database series are bounded; say so on
	// /metrics rather than only in the JSON snapshot.
	WriteGauge(w, MetricPrefix+"terrabase_view_truncated",
		Bool(view.Truncated || len(view.Databases) > maxLabeledDatabases))
	for index, database := range view.Databases {
		if index >= maxLabeledDatabases {
			break
		}
		labels := []string{"database", database.DatabaseID, "partition", database.PartitionID}
		WriteGauge(w, Series(MetricPrefix+"terrabase_replicas", slices.Concat(labels, []string{"state", "desired"})...),
			float64(database.DesiredSeats))
		if database.Readiness == "observed" {
			WriteGauge(w, Series(MetricPrefix+"terrabase_replicas", slices.Concat(labels, []string{"state", "serving"})...),
				float64(database.Serving))
		}
		WriteGauge(w, Series(MetricPrefix+"terrabase_generation", labels...), float64(database.Generation))
		if rollout := database.Rollout; rollout != nil {
			WriteGauge(w, Series(MetricPrefix+"rollout_progress_ratio", labels...), rollout.Progress())
			WriteGauge(w, Series(MetricPrefix+"rollout_seats_completed", labels...), float64(rollout.Completed))
		}
	}
}

func (health *Health) Evaluate(ctx context.Context) (bool, []CheckResult) {
	if health == nil {
		return false, nil
	}
	health.mu.RLock()
	checks := append([]Check(nil), health.checks...)
	health.mu.RUnlock()
	if len(checks) == 0 {
		return false, []CheckResult{{Name: "startup", Detail: "runtime checks are not registered"}}
	}
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()
	ready := true
	results := make([]CheckResult, 0, len(checks))
	for _, check := range checks {
		ok, detail := check.Run(ctx)
		ready = ready && ok
		results = append(results, CheckResult{Name: check.Name, OK: ok, Detail: detail})
	}
	return ready, results
}

func NewServer(config Config, deps ServerDeps) (*Server, error) {
	if err := config.Validate(); err != nil {
		return nil, err
	}
	var token []byte
	if config.BearerTokenFile != "" {
		var err error
		if token, err = readBearerToken(config.BearerTokenFile); err != nil {
			return nil, err
		}
	}
	return newServer(config, token, deps)
}

func NewTokenServer(config Config, token string, deps ServerDeps) (*Server, error) {
	checked, err := checkBearerToken([]byte(token))
	if err != nil {
		return nil, err
	}
	// The token stands in for the file Validate requires off loopback.
	config.BearerTokenFile = "token"
	if err := config.Validate(); err != nil {
		return nil, err
	}
	return newServer(config, checked, deps)
}

func newServer(config Config, token []byte, deps ServerDeps) (*Server, error) {
	if deps.Registry == nil || deps.Health == nil {
		return nil, errors.New("observability server requires a registry and health checks")
	}
	manager := &sessions{secure: config.TLSCertFile != ""}
	if deps.LocalSessions {
		manager.local = make(map[string]struct{})
	}
	server := &Server{mux: http.NewServeMux(), deps: deps, sessions: manager, token: token}
	server.catalog = &metricCatalog{registry: deps.Registry}
	if deps.Sessions != nil && token != nil {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		if err := server.SetSessionStore(ctx, deps.Sessions); err != nil {
			return nil, err
		}
	}
	server.mux.HandleFunc("GET /healthz", func(writer http.ResponseWriter, _ *http.Request) {
		writePlain(writer, http.StatusOK, "ok\n")
	})
	server.mux.HandleFunc("GET /readyz", server.readyz)
	server.Handle("GET /metrics", http.HandlerFunc(server.metrics))
	server.HandleAuthenticated("GET /v1/metrics/catalog", http.HandlerFunc(server.metricCatalogHTTP))
	if deps.Snapshots != nil {
		server.HandleSnapshots(deps.Snapshots)
	}
	if deps.Cluster != nil {
		server.HandleCluster(deps.Cluster)
	}
	if deps.Events != nil {
		server.Handle("GET /v1/events", http.HandlerFunc(server.events))
	}
	return server, nil
}

func (server *Server) Handle(pattern string, handler http.Handler) {
	server.mux.Handle(pattern, server.authenticate(handler))
}

func (server *Server) HandleAuthenticated(pattern string, handler http.Handler) {
	server.Handle(pattern, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if server.token == nil {
			writePlain(w, http.StatusServiceUnavailable, "authenticated API requires a configured token\n")
			return
		}
		handler.ServeHTTP(w, r)
	}))
}

func (server *Server) ServeHTTP(writer http.ResponseWriter, request *http.Request) {
	// A proxy hop would make the bind address meaningless as an access
	// control, exactly as for the host enrollment listener.
	if request.Header.Get("Forwarded") != "" || request.Header.Get("X-Forwarded-For") != "" ||
		request.Header.Get("X-Real-IP") != "" {
		writePlain(writer, http.StatusBadRequest, "proxied requests are not accepted\n")
		return
	}
	// Without a token the loopback bind is the only control, and DNS
	// rebinding defeats it for any route reachable under a hostname. Every
	// route of a tokenless listener, not only the dashboard's, therefore
	// requires an IP literal or localhost as the Host.
	if server.token == nil && !LiteralHost(request.Host) {
		writePlain(writer, http.StatusMisdirectedRequest, "address this listener by IP or localhost\n")
		return
	}
	server.mux.ServeHTTP(writer, request)
}

func (server *Server) authenticate(next http.Handler) http.Handler {
	return http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		if server.token != nil && !bearerMatches(request.Header.Get("Authorization"), server.token) {
			authenticated := false
			if request.Header.Get("Authorization") == "" && server.loginMounted.Load() {
				var err error
				authenticated, err = server.sessions.authenticated(request)
				if err != nil {
					writePlain(writer, http.StatusServiceUnavailable, "session storage unavailable\n")
					return
				}
			}
			if !authenticated {
				if server.loginMounted.Load() && wantsLoginPage(request) {
					http.Redirect(writer, request, "/login?next="+url.QueryEscape(LocalRedirectPath(request.URL.RequestURI())),
						http.StatusSeeOther)
					return
				}
				writer.Header().Set("WWW-Authenticate", `Bearer realm="ts-orch"`)
				writePlain(writer, http.StatusUnauthorized, "unauthorized\n")
				return
			}
		}
		if server.token != nil && server.loginMounted.Load() && request.Header.Get("Authorization") == "" {
			if cookie, err := request.Cookie(SessionCookieName); err == nil {
				http.SetCookie(writer, server.sessions.cookie(cookie.Value))
			}
		}
		next.ServeHTTP(writer, request)
	})
}

func writeJSON(writer http.ResponseWriter, value any) {
	data, err := json.Marshal(value)
	if err != nil {
		writePlain(writer, http.StatusInternalServerError, "encode failed\n")
		return
	}
	writer.Header().Set("Content-Type", "application/json")
	writer.Header().Set("Cache-Control", "no-store")
	writer.Header().Set("X-Content-Type-Options", "nosniff")
	_, _ = writer.Write(append(data, '\n'))
}

