func eventsOverHTTP(t *testing.T, bus *EventBus, query string) []Event {
	t.Helper()
	service, err := NewServer(Config{}, ServerDeps{Registry: NewRegistry(false), Health: new(Health), Events: bus})
	if err != nil {
		t.Fatal(err)
	}
	endpoint := httptest.NewServer(service)
	defer endpoint.Close()
	response, err := endpoint.Client().Get(endpoint.URL + "/v1/events" + query)
	if err != nil {
		t.Fatal(err)
	}
	defer response.Body.Close()
	var events []Event
	if err := json.NewDecoder(response.Body).Decode(&events); err != nil {
		t.Fatal(err)
	}
	return events
}

func TestMain(m *testing.M) {
	journalStream = func() bool { return false }
	os.Exit(m.Run())
}

func newLogOutput(t *testing.T) *logOutput {
	t.Helper()
	file, err := os.Create(filepath.Join(t.TempDir(), "process.log"))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		if err := file.Close(); err != nil {
			t.Error(err)
		}
	})
	return &logOutput{File: file, t: t}
}

func (output *logOutput) Bytes() []byte {
	output.t.Helper()
	data, err := os.ReadFile(output.Name())
	if err != nil {
		output.t.Fatal(err)
	}
	return data
}

func (bus *EventBus) Publish(event Event) Event {
	if bus == nil {
		return event
	}
	if event.Time.IsZero() {
		event.Time = time.Now().UTC()
	}
	bus.mu.Lock()
	bus.initLocked()
	bus.sequence++
	event.Sequence = bus.sequence
	index := (bus.start + bus.size) % len(bus.ring)
	if bus.size == len(bus.ring) {
		bus.start = (bus.start + 1) % len(bus.ring)
	} else {
		bus.size++
	}
	bus.ring[index] = event
	for subscriber := range bus.subscribers {
		select {
		case subscriber.events <- event:
		default:
			bus.dropped.Add(1)
		}
	}
	bus.mu.Unlock()
	bus.published.Add(1)
	return event
}

func (bus *EventBus) Since(after uint64, limit int) []Event {
	if bus == nil {
		return nil
	}
	bus.mu.Lock()
	defer bus.mu.Unlock()
	events := make([]Event, 0, bus.size)
	for offset := range bus.size {
		event := bus.ring[(bus.start+offset)%len(bus.ring)]
		if event.Sequence > after {
			events = append(events, event)
		}
	}
	if limit > 0 && len(events) > limit {
		events = events[len(events)-limit:]
	}
	return events
}

func (bus *EventBus) Subscribe(ctx context.Context, buffer int) <-chan Event {
	if buffer <= 0 {
		buffer = 64
	}
	subscriber := &eventSubscriber{events: make(chan Event, buffer)}
	if bus == nil {
		close(subscriber.events)
		return subscriber.events
	}
	bus.mu.Lock()
	bus.initLocked()
	bus.subscribers[subscriber] = struct{}{}
	bus.mu.Unlock()
	context.AfterFunc(ctx, func() {
		bus.mu.Lock()
		delete(bus.subscribers, subscriber)
		bus.mu.Unlock()
		close(subscriber.events)
	})
	return subscriber.events
}

func (bus *EventBus) Stats() (published, dropped uint64) {
	if bus == nil {
		return 0, 0
	}
	return bus.published.Load(), bus.dropped.Load()
}

func eventFromRecord(record slog.Record, scoped []slog.Attr, groups []string) Event {
	event := Event{Time: record.Time.UTC(), Level: record.Level.String(), Message: record.Message}
	attrs := make(map[string]string, record.NumAttrs()+len(scoped))
	add := func(attr slog.Attr) {
		prefix := ""
		for _, group := range groups {
			prefix += group + "."
		}
		flattenAttr(attrs, prefix, attr)
	}
	for _, attr := range scoped {
		add(attr)
	}
	record.Attrs(func(attr slog.Attr) bool {
		add(attr)
		return true
	})
	if component, ok := attrs[ComponentKey]; ok {
		event.Component = component
		delete(attrs, ComponentKey)
	}
	delete(attrs, EventKey)
	// A trace is new on every pass, so keeping its ID would defeat the repeat window.
	delete(attrs, TraceIDKey)
	if len(attrs) > 0 {
		event.Attrs = attrs
	}
	return event
}

func flattenAttr(attrs map[string]string, prefix string, attr slog.Attr) {
	attr.Value = attr.Value.Resolve()
	if attr.Equal(slog.Attr{}) || len(attrs) >= maxEventAttrs {
		return
	}
	if attr.Value.Kind() == slog.KindGroup {
		nested := prefix
		if attr.Key != "" {
			nested += attr.Key + "."
		}
		for _, child := range attr.Value.Group() {
			flattenAttr(attrs, nested, child)
		}
		return
	}
	value := attr.Value.String()
	if len(value) > maxEventAttrBytes {
		// Cut on a rune boundary so a long non-ASCII value never carries a
		// split UTF-8 sequence into the event.
		cut := maxEventAttrBytes
		for cut > 0 && !utf8.RuneStart(value[cut]) {
			cut--
		}
		value = value[:cut] + "..."
	}
	attrs[prefix+attr.Key] = value
}

func NewLogger(output io.Writer, config LogConfig, bus *EventBus, attrs ...slog.Attr) (*slog.Logger, error) {
	config, level, err := ParseLogConfig(config.Format, config.Level)
	if err != nil {
		return nil, err
	}
	if journalStream() {
		output = journalWriter{next: output}
	}
	options := &slog.HandlerOptions{Level: level, ReplaceAttr: utcTime}
	var handler slog.Handler
	if config.Format == "logfmt" {
		handler = slog.NewTextHandler(output, options)
	} else {
		handler = slog.NewJSONHandler(output, options)
	}
	if bus != nil {
		handler = &EventTee{next: handler, bus: bus, counters: newLogCounters(), repeats: newEventRepeats()}
	}
	handler = &redactingHandler{next: handler}
	if len(attrs) > 0 {
		handler = handler.WithAttrs(attrs)
	}
	return slog.New(handler), nil
}

func (tee *EventTee) Enabled(ctx context.Context, level slog.Level) bool {
	return level >= slog.LevelInfo || tee.next.Enabled(ctx, level)
}

func (tee *EventTee) Handle(ctx context.Context, record slog.Record) error {
	if record.Level >= slog.LevelWarn || tee.marked(record) {
		event := eventFromRecord(record, tee.eventScope(), tee.groups)
		if tee.repeats.admit(event, record.Time) {
			tee.bus.Publish(event)
		}
	}
	if !tee.next.Enabled(ctx, record.Level) {
		return nil
	}
	tee.counters.count(record.Level)
	return tee.next.Handle(ctx, record)
}

func (repeats *eventRepeats) admit(event Event, now time.Time) bool {
	if repeats == nil {
		return true
	}
	if now.IsZero() {
		now = time.Now()
	}
	key := eventRepeatKey(event)
	repeats.mu.Lock()
	defer repeats.mu.Unlock()
	if last, ok := repeats.last[key]; ok && now.Sub(last) >= 0 && now.Sub(last) < eventRepeatWindow {
		repeats.suppressed.Add(1)
		return false
	}
	if len(repeats.last) >= maxEventRepeats {
		for existing, at := range repeats.last {
			if now.Sub(at) >= eventRepeatWindow {
				delete(repeats.last, existing)
			}
		}
		if len(repeats.last) >= maxEventRepeats {
			clear(repeats.last)
		}
	}
	repeats.last[key] = now
	return true
}

func eventRepeatKey(event Event) string {
	var key strings.Builder
	key.WriteString(event.Level)
	key.WriteByte(0)
	key.WriteString(event.Component)
	key.WriteByte(0)
	key.WriteString(event.Message)
	for _, name := range slices.Sorted(maps.Keys(event.Attrs)) {
		key.WriteByte(0)
		key.WriteString(name)
		key.WriteByte('=')
		key.WriteString(event.Attrs[name])
	}
	return key.String()
}

func (h *redactingHandler) Handle(ctx context.Context, record slog.Record) error {
	s := logSanitizer{remaining: maxLogAttrs - 1 - h.used, truncated: h.truncated}
	if h.component.Key != "" {
		s.remaining--
	}
	clean := slog.NewRecord(record.Time, record.Level, s.text(record.Message, maxLogMessageBytes), record.PC)
	// The trace ID follows the static attributes and precedes the call's own.
	if trace := TraceID(ctx); trace != "" {
		s.remaining--
		clean.AddAttrs(slog.String(TraceIDKey, trace))
	}
	// Preserve selection and component even when ordinary attributes exhaust
	// the budget. This scan does not resolve or format application values.
	var event, component slog.Attr
	eventIndex, componentIndex := -1, -1
	index := 0
	record.Attrs(func(a slog.Attr) bool {
		if a.Key == EventKey && a.Value.Kind() == slog.KindBool {
			if event.Key == "" || !event.Value.Bool() {
				event = a
				eventIndex = index
			}
		}
		if a.Key == ComponentKey {
			component = a
			componentIndex = index
		}
		index++
		return true
	})
	// Reserve metadata capacity, but emit it in its original position so an
	// inline group and a root component keep their last-value-wins ordering.
	for _, a := range []*slog.Attr{&event, &component} {
		if a.Key != "" {
			*a, _ = s.attr(*a, h.depth, h.sensitive)
		}
	}
	index = -1
	record.Attrs(func(a slog.Attr) bool {
		index++
		if index == eventIndex {
			if event.Key != "" {
				clean.AddAttrs(event)
			}
			return true
		}
		if index == componentIndex {
			if component.Key != "" {
				clean.AddAttrs(component)
			}
			return true
		}
		if a.Key == ComponentKey || (a.Key == EventKey && eventIndex >= 0) {
			return true
		}
		if h.blocked || s.remaining <= 0 {
			s.truncated = true
			return true
		}
		if prepared, ok := s.attr(a, h.depth, h.sensitive); ok {
			clean.AddAttrs(prepared)
		}
		return true
	})
	if s.truncated {
		clean.AddAttrs(slog.Bool(logTruncatedKey, true))
	}
	return h.next.Handle(ctx, clean)
}

func (s *logSanitizer) attr(a slog.Attr, depth int, sensitive bool) (slog.Attr, bool) {
	if s.remaining <= 0 {
		s.truncated = true
		return slog.Attr{}, false
	}
	s.remaining--
	if a.Key == "" && a.Value.Kind() == slog.KindAny && a.Value.Any() == nil {
		return slog.Attr{}, false
	}
	key := s.text(a.Key, maxLogNameBytes)
	// Never invoke a valuer/error/stringer for a known sensitive field.
	if (sensitive || sensitiveLogKey(a.Key)) && !(a.Key == EventKey && a.Value.Kind() == slog.KindBool) {
		return slog.String(key, redactedLogValue), true
	}
	value := s.resolve(a.Value)
	if value.Kind() == slog.KindGroup {
		if depth >= maxLogDepth {
			s.truncated = true
			return slog.String(key, omittedLogValue), true
		}
		var children []slog.Attr
		for _, child := range value.Group() {
			if s.remaining <= 0 {
				s.truncated = true
				break
			}
			if prepared, ok := s.attr(child, depth+1, sensitive); ok {
				children = append(children, prepared)
			}
		}
		return slog.Attr{Key: key, Value: slog.GroupValue(children...)}, true
	}
	if value.Kind() == slog.KindTime {
		// Event values expose zone names, unlike RFC3339 log output.
		at := value.Time()
		zone, offset := at.Zone()
		value = slog.TimeValue(at.In(time.FixedZone(s.text(zone, maxLogNameBytes), offset)))
	} else if value.Kind() == slog.KindString {
		value = slog.StringValue(s.text(value.String(), maxLogValueBytes))
	} else if value.Kind() == slog.KindAny {
		value = s.anyValue(value.Any(), depth)
	}
	return slog.Attr{Key: key, Value: value}, true
}

func (s *logSanitizer) text(value string, limit int) string {
	// Fail closed rather than cutting an unfinished credential at the scan
	// boundary. All regex work is RE2 and limited to this input size.
	if len(value) > maxLogScanBytes {
		s.truncated = true
		return omittedLogValue
	}
	if !utf8.ValidString(value) {
		s.truncated = true
		value = strings.ToValidUTF8(value, "�")
	}
	value = logPEM.ReplaceAllString(value, redactedLogValue)
	value = logURL.ReplaceAllStringFunc(value, func(raw string) string {
		parsed, err := url.Parse(raw)
		if err != nil {
			return redactedLogValue
		}
		if parsed.User != nil {
			parsed.User = url.User(redactedLogValue)
		}
		return parsed.String()
	})
	value = logQuery.ReplaceAllStringFunc(value, func(raw string) string {
		key, _, _ := strings.Cut(raw[1:], "=")
		decoded, err := url.QueryUnescape(key)
		if err != nil || sensitiveLogKey(decoded) {
			return raw[:1] + key + "=" + redactedLogValue
		}
		return raw
	})
	value = logBearer.ReplaceAllString(value, "Bearer "+redactedLogValue)
	value = logJWT.ReplaceAllStringFunc(value, func(raw string) string {
		header, _, _ := strings.Cut(raw, ".")
		decoded, err := base64.RawURLEncoding.DecodeString(header)
		if err == nil && strings.HasPrefix(strings.TrimSpace(string(decoded)), "{") && json.Valid(decoded) {
			return redactedLogValue
		}
		return raw
	})
	value = logSeed.ReplaceAllString(value, redactedLogValue)
	if len(value) > limit {
		s.truncated = true
		cut := limit - len("...")
		for cut > 0 && !utf8.RuneStart(value[cut]) {
			cut--
		}
		value = value[:cut] + "..."
	}
	// Clone even short substrings: scoped strings must not pin large input buffers.
	return strings.Clone(value)
}

func (server *Server) events(writer http.ResponseWriter, request *http.Request) {
	query := request.URL.Query()
	after, _ := strconv.ParseUint(query.Get("after"), 10, 64)
	limit, err := strconv.Atoi(query.Get("limit"))
	if err != nil || limit <= 0 || limit > DefaultEventCapacity {
		limit = 200
	}
	writeJSON(writer, server.deps.Events.Since(after, limit))
}

func NewServer(config Config, deps ServerDeps) (*Server, error) {
	if err := config.Validate(); err != nil {
		return nil, err
	}
	var token []byte
	if config.BearerTokenFile != "" {
		var err error
		if token, err = readBearerToken(config.BearerTokenFile); err != nil {
			return nil, err
		}
	}
	return newServer(config, token, deps)
}

func NewTokenServer(config Config, token string, deps ServerDeps) (*Server, error) {
	checked, err := checkBearerToken([]byte(token))
	if err != nil {
		return nil, err
	}
	// The token stands in for the file Validate requires off loopback.
	config.BearerTokenFile = "token"
	if err := config.Validate(); err != nil {
		return nil, err
	}
	return newServer(config, checked, deps)
}

func newServer(config Config, token []byte, deps ServerDeps) (*Server, error) {
	if deps.Registry == nil || deps.Health == nil {
		return nil, errors.New("observability server requires a registry and health checks")
	}
	manager := &sessions{secure: config.TLSCertFile != ""}
	if deps.LocalSessions {
		manager.local = make(map[string]struct{})
	}
	server := &Server{mux: http.NewServeMux(), deps: deps, sessions: manager, token: token}
	server.catalog = &metricCatalog{registry: deps.Registry}
	if deps.Sessions != nil && token != nil {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		if err := server.SetSessionStore(ctx, deps.Sessions); err != nil {
			return nil, err
		}
	}
	server.mux.HandleFunc("GET /healthz", func(writer http.ResponseWriter, _ *http.Request) {
		writePlain(writer, http.StatusOK, "ok\n")
	})
	server.mux.HandleFunc("GET /readyz", server.readyz)
	server.Handle("GET /metrics", http.HandlerFunc(server.metrics))
	server.HandleAuthenticated("GET /v1/metrics/catalog", http.HandlerFunc(server.metricCatalogHTTP))
	if deps.Snapshots != nil {
		server.HandleSnapshots(deps.Snapshots)
	}
	if deps.Cluster != nil {
		server.HandleCluster(deps.Cluster)
	}
	if deps.Events != nil {
		server.Handle("GET /v1/events", http.HandlerFunc(server.events))
	}
	return server, nil
}

func (server *Server) Handle(pattern string, handler http.Handler) {
	server.mux.Handle(pattern, server.authenticate(handler))
}

func (server *Server) HandleAuthenticated(pattern string, handler http.Handler) {
	server.Handle(pattern, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if server.token == nil {
			writePlain(w, http.StatusServiceUnavailable, "authenticated API requires a configured token\n")
			return
		}
		handler.ServeHTTP(w, r)
	}))
}

func (server *Server) ServeHTTP(writer http.ResponseWriter, request *http.Request) {
	// A proxy hop would make the bind address meaningless as an access
	// control, exactly as for the host enrollment listener.
	if request.Header.Get("Forwarded") != "" || request.Header.Get("X-Forwarded-For") != "" ||
		request.Header.Get("X-Real-IP") != "" {
		writePlain(writer, http.StatusBadRequest, "proxied requests are not accepted\n")
		return
	}
	// Without a token the loopback bind is the only control, and DNS
	// rebinding defeats it for any route reachable under a hostname. Every
	// route of a tokenless listener, not only the dashboard's, therefore
	// requires an IP literal or localhost as the Host.
	if server.token == nil && !LiteralHost(request.Host) {
		writePlain(writer, http.StatusMisdirectedRequest, "address this listener by IP or localhost\n")
		return
	}
	server.mux.ServeHTTP(writer, request)
}

func (server *Server) authenticate(next http.Handler) http.Handler {
	return http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		if server.token != nil && !bearerMatches(request.Header.Get("Authorization"), server.token) {
			authenticated := false
			if request.Header.Get("Authorization") == "" && server.loginMounted.Load() {
				var err error
				authenticated, err = server.sessions.authenticated(request)
				if err != nil {
					writePlain(writer, http.StatusServiceUnavailable, "session storage unavailable\n")
					return
				}
			}
			if !authenticated {
				if server.loginMounted.Load() && wantsLoginPage(request) {
					http.Redirect(writer, request, "/login?next="+url.QueryEscape(LocalRedirectPath(request.URL.RequestURI())),
						http.StatusSeeOther)
					return
				}
				writer.Header().Set("WWW-Authenticate", `Bearer realm="ts-orch"`)
				writePlain(writer, http.StatusUnauthorized, "unauthorized\n")
				return
			}
		}
		if server.token != nil && server.loginMounted.Load() && request.Header.Get("Authorization") == "" {
			if cookie, err := request.Cookie(SessionCookieName); err == nil {
				http.SetCookie(writer, server.sessions.cookie(cookie.Value))
			}
		}
		next.ServeHTTP(writer, request)
	})
}

func writeJSON(writer http.ResponseWriter, value any) {
	data, err := json.Marshal(value)
	if err != nil {
		writePlain(writer, http.StatusInternalServerError, "encode failed\n")
		return
	}
	writer.Header().Set("Content-Type", "application/json")
	writer.Header().Set("Cache-Control", "no-store")
	writer.Header().Set("X-Content-Type-Options", "nosniff")
	_, _ = writer.Write(append(data, '\n'))
}

